1	import {
2	    Button,
3	    Dialog,
4	    DialogContent,
5	    DialogTitle,
6	    Grid,
7	    Stack,
8	    Typography,
9	} from '@mui/material';
10	import { useEffect, useState } from 'react';
11	import { useGetIdentity, useGetList } from 'react-admin';
12	import { DealCardContent } from './DealCard';
13	import { Deal } from '../types';
14	import { DialogCloseButton } from '../misc/DialogCloseButton';
15	
16	export const DealArchivedList = () => {
17	    const { identity } = useGetIdentity();
18	    const {
19	        data: archivedLists,
20	        total,
21	        isPending,
22	    } = useGetList('deals', {
23	        pagination: { page: 1, perPage: 1000 },
24	        sort: { field: 'archived_at', order: 'DESC' },
25	        filter: { 'archived_at@not.is': null },
26	    });
27	    const [openDialog, setOpenDialog] = useState(false);
28	
29	    useEffect(() => {
30	        if (!isPending && total === 0) {
31	            setOpenDialog(false);
32	        }
33	    }, [isPending, total]);
34	
35	    useEffect(() => {
36	        setOpenDialog(false);
37	    }, [archivedLists]);
38	
39	    if (!identity || isPending || !total || !archivedLists) return null;
40	
41	    // Group archived lists by date
42	    const archivedListsByDate: { [date: string]: Deal[] } =
43	        archivedLists.reduce(
44	            (acc, deal) => {
45	                const date = new Date(deal.archived_at).toDateString();
46	                if (!acc[date]) {
47	                    acc[date] = [];
48	                }
49	                acc[date].push(deal);
50	                return acc;
51	            },
52	            {} as { [date: string]: Deal[] }
53	        );
54	
55	    return (
56	        <>
57	            <Button
58	                variant="text"
59	                onClick={() => setOpenDialog(true)}
60	                sx={{ my: 1 }}
61	            >
62	                View archived deals
63	            </Button>
64	            <Dialog
65	                open={openDialog}
66	                onClose={() => setOpenDialog(false)}
67	                fullWidth
68	                maxWidth="lg"
69	            >
70	                <DialogCloseButton onClose={() => setOpenDialog(false)} />
71	                <DialogTitle>Archived Deals</DialogTitle>
72	                <DialogContent>
73	                    <Stack gap={2}>
74	                        {Object.entries(archivedListsByDate).map(
75	                            ([date, deals]) => (
76	                                <Stack key={date} gap={1}>
77	                                    <Typography
78	                                        variant="body1"
79	                                        fontWeight="bold"
80	                                    >
81	                                        {getRelativeTimeString(date)}
82	                                    </Typography>
83	                                    <Grid container spacing={2}>
84	                                        {deals.map((deal: Deal) => (
85	                                            <Grid
86	                                                item
87	                                                xs={12}
88	                                                sm={6}
89	                                                md={4}
90	                                                key={deal.id}
91	                                            >
92	                                                <DealCardContent deal={deal} />
93	                                            </Grid>
94	                                        ))}
