43	        <>
44	            <Stack
45	                direction={linkPosition === 'right' ? 'row' : 'column'}
46	                alignItems={'center'}
47	                gap={linkPosition === 'right' ? 2 : 0.5}
48	                borderRadius={1}
49	                p={props.backgroundImageColor ? 1 : 0}
50	                sx={{
51	                    backgroundColor:
52	                        props.backgroundImageColor || 'transparent',
53	                }}
