57	                ) : (
58	                    <Box component={'img'} {...commonProps} />
59	                )}
60	                {linkPosition !== 'none' && (
61	                    <Typography
62	                        component={Link}
63	                        variant="caption"
64	                        onClick={() => setIsDialogOpen(true)}
65	                        textAlign="center"
66	                        sx={{ display: 'inline', cursor: 'pointer' }}
67	                    >
68	                        Change
69	                    </Typography>
70	                )}
71	            </Stack>
72	            <ImageEditorDialog
73	                open={isDialogOpen}
74	                onClose={() => setIsDialogOpen(false)}
75	                {...props}
76	            />
77	        </>
78	    );
79	};
80	
81	const ImageEditorDialog = (props: ImageEditorDialogProps) => {
82	    const { setValue, handleSubmit } = useFormContext();
83	    const cropperRef = createRef<ReactCropperElement>();
84	    const initialValue = useFieldValue(props);
85	    const [file, setFile] = useState<File | undefined>();
86	    const [imageSrc, setImageSrc] = useState<string | undefined>(
87	        initialValue?.src
88	    );
89	    const onDrop = useCallback((files: File[]) => {
90	        const preview = URL.createObjectURL(files[0]);
91	        setFile(files[0]);
92	        setImageSrc(preview);
93	    }, []);
94	
95	    const updateImage = () => {
96	        const cropper = cropperRef.current?.cropper;
97	        const croppedImage = cropper?.getCroppedCanvas().toDataURL();
98	        if (croppedImage) {
99	            setImageSrc(croppedImage);
100	
101	            const newFile = file ?? new File([], initialValue?.src);
102	            setValue(
103	                props.source,
104	                {
105	                    src: croppedImage,
106	                    title: newFile.name,
107	                    rawFile: newFile,
108	                },
109	                { shouldDirty: true }
110	            );
111	            props.onClose();
112	
113	            if (props.onSave) {
114	                handleSubmit(props.onSave)();
115	            }
116	        }
117	    };
118	
119	    const deleteImage = () => {
120	        setValue(props.source, null, { shouldDirty: true });
121	        if (props.onSave) {
122	            handleSubmit(props.onSave)();
123	        }
124	        props.onClose();
125	    };
126	
127	    const { getRootProps, getInputProps } = useDropzone({
