145	                            border-radius: 50%;
146	                        }
147	                    `}
148	                </style>
149	            )}
150	            <DialogCloseButton onClose={props.onClose} />
151	            <DialogTitle>Upload and resize image</DialogTitle>
152	            <DialogContent>
153	                <Stack gap={2} justifyContent="center">
154	                    <Stack
155	                        direction="row"
156	                        justifyContent="center"
157	                        {...getRootProps()}
158	                        sx={{
159	                            backgroundColor: 'rgba(0, 0, 0, 0.05)',
160	                            cursor: 'pointer',
161	                        }}
162	                    >
163	                        <input {...getInputProps()} />
164	                        <p>Drop a file to upload, or click to select it.</p>
165	                    </Stack>
166	                    <Cropper
167	                        ref={cropperRef}
168	                        src={imageSrc}
169	                        aspectRatio={1}
170	                        guides={false}
171	                        cropBoxResizable={false}
172	                    />
173	                </Stack>
174	            </DialogContent>
175	            <DialogActions sx={{ p: 0 }}>
176	                <Toolbar
177	                    sx={{ width: '100%', justifyContent: 'space-between' }}
178	                >
179	                    <Button variant="contained" onClick={updateImage}>
180	                        Update Image
181	                    </Button>
182	                    <Button variant="text" color="error" onClick={deleteImage}>
183	                        Delete
184	                    </Button>
185	                </Toolbar>
186	            </DialogActions>
187	        </Dialog>
188	    );
189	};
190	
191	export default ImageEditorField;
192	
